class Solution:
    def maximumLengthSubstring(self, s: str) -> int:
        left = 0
        max_len = 0
        counts = {}

        for right, char in enumerate(s):
            counts[char] = counts.get(char, 0) + 1

            while counts[char] > 2:
                left_char = s[left]
                counts[left_char] -= 1
                left += 1

            max_len = max(max_len, right - left + 1)

        return max_len
