class Solution:
    def hasIncreasingSubarrays(self, nums: List[int], k: int) -> bool:
        n = len(nums)

        # Iterate through all possible starting positions 'i' for the first subarray.
        # The first subarray starts at 'i' and ends at 'i + k - 1'.
        # The second subarray starts at 'i + k' and ends at 'i + 2k - 1'.
        # The loop runs from i = 0 to i = n - 2*k.
        for i in range(n - 2 * k + 1):

            # Check if the first subarray nums[i : i+k] is strictly increasing.
            # A subarray is strictly increasing if nums[j] < nums[j+1] for all j in the range.
            first_inc = True
            for j in range(i, i + k - 1):
                if nums[j] >= nums[j + 1]:
                    first_inc = False
                    break

            if first_inc:
                # If the first subarray is strictly increasing, check the second one.
                # The second subarray starts at i + k.
                second_inc = True
                for j in range(i + k, i + 2 * k - 1):
                    if nums[j] >= nums[j + 1]:
                        second_inc = False
                        break

                if second_inc:
                    return True

        return False
